import React, { useState } from 'react';
import { Modal, Button, Form, Alert, Row, Col } from 'react-bootstrap';
import emailjs from 'emailjs-com'; // ← ADICIONE ESTA LINHA
import './ContactModal.css';

const ContactModal = ({ show, handleClose }) => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });
    const [showAlert, setShowAlert] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [alertType, setAlertType] = useState('success'); // 'success' ou 'error'

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            // Configuração do EmailJS
            const templateParams = {
                from_name: formData.name,
                from_email: formData.email,
                subject: formData.subject,
                message: formData.message,
                to_email: 'seu-email@gmail.com' // SEU EMAIL AQUI
            };

            // Envia o email
            await emailjs.send(
                'service_rw65j59',     // ID do serviço (criar no EmailJS)
                'qy5pl8z',    // ID do template (criar no EmailJS)
                templateParams,
                'afhxTW6cc58fNJRwz'      // Chave pública (pegar no EmailJS)
            );

            // Sucesso
            setAlertType('success');
            setShowAlert(true);
            setFormData({ name: '', email: '', subject: '', message: '' });

            setTimeout(() => {
                setShowAlert(false);
                handleClose();
            }, 3000);

        } catch (error) {
            // Erro
            setAlertType('error');
            setShowAlert(true);
            console.error('Erro ao enviar email:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleModalClose = () => {
        setFormData({ name: '', email: '', subject: '', message: '' });
        setShowAlert(false);
        handleClose();
    };

    return (
        <Modal show={show} onHide={handleModalClose} size="lg" centered className="contact-modal">
            <Modal.Header closeButton className="modal-header-custom">
                <Modal.Title>CONTATO</Modal.Title>
            </Modal.Header>

            <Modal.Body>
                <div className="text-center mb-4">
                    <p>Entre em contato comigo para discutir oportunidades, projetos ou colaborações.</p>
                </div>

                <Form onSubmit={handleSubmit}>
                    {showAlert && (
                        <Alert variant={alertType === 'success' ? 'success' : 'danger'} className="alert-message">
                            <i className={`bx ${alertType === 'success' ? 'bx-check-circle' : 'bx-error'}`}></i>
                            {alertType === 'success'
                                ? 'Sua mensagem foi enviada com sucesso! Obrigado.'
                                : 'Erro ao enviar mensagem. Tente novamente.'
                            }
                        </Alert>
                    )}

                    {/* Resto do formulário permanece igual */}
                    <Row>
                        <Col md={6} className="form-group">
                            <Form.Label htmlFor="name">Seu Nome</Form.Label>
                            <Form.Control
                                type="text"
                                name="name"
                                id="name"
                                value={formData.name}
                                onChange={handleChange}
                                required
                                placeholder="Digite seu nome completo"
                            />
                        </Col>
                        <Col md={6} className="form-group">
                            <Form.Label htmlFor="email">Seu Email</Form.Label>
                            <Form.Control
                                type="email"
                                name="email"
                                id="email"
                                value={formData.email}
                                onChange={handleChange}
                                required
                                placeholder="seu.email@exemplo.com"
                            />
                        </Col>
                    </Row>

                    <div className="form-group mt-3">
                        <Form.Label htmlFor="subject">Assunto</Form.Label>
                        <Form.Control
                            type="text"
                            name="subject"
                            id="subject"
                            value={formData.subject}
                            onChange={handleChange}
                            required
                            placeholder="Assunto da mensagem"
                        />
                    </div>

                    <div className="form-group mt-3">
                        <Form.Label htmlFor="message">Mensagem</Form.Label>
                        <Form.Control
                            as="textarea"
                            rows="5"
                            name="message"
                            id="message"
                            value={formData.message}
                            onChange={handleChange}
                            required
                            placeholder="Descreva sua mensagem aqui..."
                        />
                    </div>

                    <div className="text-center mt-4">
                        <Button
                            type="submit"
                            className="contact-btn"
                            disabled={isSubmitting}
                        >
                            {isSubmitting ? (
                                <>
                                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                    Enviando...
                                </>
                            ) : (
                                <>
                                    <i className="bx bx-send me-2"></i>
                                    Enviar Mensagem
                                </>
                            )}
                        </Button>
                    </div>
                </Form>
            </Modal.Body>
        </Modal>
    );
};

export default ContactModal;
